def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                x, y = stack.pop()
                comp.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            comps.append(comp)

    # Ignore broad background regions meeting three or more grid edges.
    candidates = []
    for comp in comps:
        sides = set()
        for r, c in comp:
            if r == 0: sides.add("top")
            if r == h - 1: sides.add("bottom")
            if c == 0: sides.add("left")
            if c == w - 1: sides.add("right")
        if len(sides) <= 2:
            candidates.append(comp)

    out = [row[:] for row in grid]
    if candidates:
        small = min(candidates, key=len)
        large = max(candidates, key=len)
        for r, c in small:
            out[r][c] = 7
        if large is not small:
            for r, c in large:
                out[r][c] = 8
    return out
